VALUES ('Höganäs Colliery (Höganäsbolaget) — Skåne', 'Höganäsbolaget (AB) — Closed 1961', NULL, NULL, NULL, 'Sweden', 'Skåne County (Scania), Höganäs Municipality', 'Höganäs, Skåne County, Sweden', 56.2003, 12.5577, 'Höganäs harbour (local coal export port — first railway in Sweden 1798 led to harbour)', 'Höganäs–Helsingborg Järnväg (Coastal line)', 1797, 164, 'Höganäs Stenkols-Bolag (Swedish coal company, later evolved into Höganäsbolaget)', '[{"year": 1797, "event": "Coal mining commenced; company formally established"}, {"year": 1798, "event": "First railway in Sweden (wooden rails) built from mine to harbour"}, {"year": 1900, "event": "Operations diversified into clay mining for ceramics as coal seams thinned"}, {"year": 1961, "event": "Coal mine officially closed — clay operations continued; Höganäs today a world ceramics company"}]'::jsonb, '[{"year": 1797, "event": "Coal mining commenced — first major coal operation in Sweden"}, {"year": 1798, "event": "First railway in Sweden constructed to transport coal to Höganäs harbour"}, {"year": 1850, "event": "Peak coal production period — major employer in Skåne"}, {"year": 1954, "event": "Underground mine cinema opened 100m below surface — unique in Sweden"}, {"year": 1961, "event": "Coal mining ceased — seams exhausted; clay mining continued"}, {"year": 2011, "event": "A-shaft from 1797 excavated and restored at Tjörröd for heritage preservation"}]'::jsonb, '[]'::jsonb, 0, 'Lignite (sub-bituminous) — Jurassic/Triassic Skåne coal', 'Lignite — thin seams (approx 5m below ground); mixed with clay layers', 3000.0, 30.0, 20.0, 2.0, NULL, 0.0, 0.0, 'Underground — shallow seams (closed 1961)', NULL, 'CLOSED 1961 — now a heritage museum (KKAM Höganäs cultural museum)', NULL, NULL, 'CLOSED', 'Höganäs harbour (historically)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
