INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Donbas Coalfield — DTEK Mines (Ukrainian-controlled)', 'DTEK Energy B.V. (Rinat Akhmetov — SCM Group) + State-owned mines (Ministry of Energy)', NULL, 'info@dtek.com', '+380 44 490 7720', 'Ukraine', 'Donetsk Oblast / Dnipropetrovsk Oblast (Ukrainian-controlled territory)', 'Pokrovsk area, Donetsk Oblast, Ukraine (Ukrainian-controlled)', 48.28, 37.38, 'Mariupol (occupied, 150km south) — currently inaccessible; Odesa (alternative)', 'Donetsk Railway (Pokrovsk hub — Ukrainian-controlled)', 1869, 156, 'Various private companies (19th century); John Hughes / British entrepreneurs', '[{"year": 1869, "event": "First commercial railway to Donbas — industrial coal extraction commenced"}, {"year": 1917, "event": "Nationalized under Soviet regime"}, {"year": 1991, "event": "Transferred to Ukrainian state on independence"}, {"year": 2002, "event": "DTEK founded — progressive privatization of profitable Donbas mines under Akhmetov"}, {"year": 2014, "event": "Ukraine lost control of occupied Donetsk/Luhansk mines (anthracite zone); DTEK shifted focus to gas coal (G-grade) mines in Ukrainian-controlled areas"}, {"year": 2022, "event": "Full-scale Russian invasion — further mines damaged or lost; production severely disrupted"}]'::jsonb, '[{"year": 1721, "event": "Coal first discovered in Donbas"}, {"year": 1869, "event": "Railway connection enabled industrial-scale mining"}, {"year": 1976, "event": "Peak Soviet production — 218 million tonnes nationally"}, {"year": 2014, "event": "War in Donbas — 22.4% production decline; Ukraine began coal imports"}, {"year": 2022, "event": "Russia''s full-scale invasion — most Ukrainian-controlled Donbas mines disrupted; DTEK Dobrotvirska, Ladyzhinska, Kurakhivska plants operating"}, {"year": 2025, "event": "Ongoing war — Pokrovsk area under military pressure; mine operations severely curtailed"}]'::jsonb, '[{"year": 2007, "event": "Zasiadko mine disaster — 101 workers killed in methane explosion"}, {"year": 2015, "event": "Zasiadko mine disaster (second major event) — multiple deaths"}, {"year": 2014, "event": "41 mines stopped in Russian-occupied territories; Ukraine lost ~90% of anthracite production"}, {"year": 2022, "event": "Russia''s invasion — systematic bombardment of Ukrainian energy infrastructure including mine-linked power plants"}]'::jsonb, NULL, 'Bituminous (gas coal G-grade, fat coal Zh, anthracite in occupied areas)', 'Bituminous — steam coal (G-grade primary in Ukrainian-controlled territory); 70% steam / 30% coking', 5500.0, 7.0, 20.0, 1.5, NULL, NULL, NULL, 'Underground — longwall (depths 300–1,800m; average 350–400m); thin seams 0.8–1.0m average', NULL, 'SEVERELY DISRUPTED — Ukraine bans thermal coal export for energy security; DTEK supplies domestic thermal power plants', NULL, NULL, 'Captive domestic supply — export banned (wartime)', 'Mariupol (occupied/inaccessible); Odesa (alternative — requires rail transit)', '["Rail (Donetsk Railway network — Ukrainian-controlled sections)"]'::jsonb, NULL, FALSE, '[]'::jsonb)
ON CONFLICT (mine_name, country) DO UPDATE SET operator = EXCLUDED.operator, license_number = EXCLUDED.license_number, contact_email = EXCLUDED.contact_email, contact_phone = EXCLUDED.contact_phone, region = EXCLUDED.region, address = EXCLUDED.address, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, nearest_port = EXCLUDED.nearest_port, nearest_railway = EXCLUDED.nearest_railway, founded_year = EXCLUDED.founded_year, years_in_operation = EXCLUDED.years_in_operation, original_owner = EXCLUDED.original_owner, ownership_changes = EXCLUDED.ownership_changes, major_milestones = EXCLUDED.major_milestones, notable_incidents = EXCLUDED.notable_incidents, estimated_mine_life_remaining_years = EXCLUDED.estimated_mine_life_remaining_years, coal_type = EXCLUDED.coal_type, grade = EXCLUDED.grade, calorific_value_kcal_kg = EXCLUDED.calorific_value_kcal_kg, moisture_percent = EXCLUDED.moisture_percent, ash_percent = EXCLUDED.ash_percent, sulfur_percent = EXCLUDED.sulfur_percent, size_mm = EXCLUDED.size_mm, annual_capacity_tonnes = EXCLUDED.annual_capacity_tonnes, available_stock_tonnes = EXCLUDED.available_stock_tonnes, mining_method = EXCLUDED.mining_method, price_per_tonne_usd = EXCLUDED.price_per_tonne_usd, price_basis = EXCLUDED.price_basis, minimum_order_tonnes = EXCLUDED.minimum_order_tonnes, payment_terms = EXCLUDED.payment_terms, contract_types = EXCLUDED.contract_types, loading_port = EXCLUDED.loading_port, transport_modes = EXCLUDED.transport_modes, lead_time_days = EXCLUDED.lead_time_days, export_license = EXCLUDED.export_license, certifications = EXCLUDED.certifications, updated_at = NOW();

INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Lviv-Volyn Coalfield — Lvivvuhillia & Volynvuhillia', 'Lvivvuhillia (Lviv State Enterprise) + Volynvuhillia (Volyn State Enterprise) — Both in decline', NULL, NULL, NULL, 'Ukraine', 'Lviv Oblast and Volyn Oblast, Western Ukraine', 'Chervonohrad (Lviv Oblast) and Novovolynsk (Volyn Oblast), Ukraine', 50.392, 24.237, 'Gdańsk (Poland, 500km) via Polish rail; Odesa (850km south)', 'Lviv–Warsaw international line (close access); Chervonohrad local rail', 1950, 75, 'Soviet state enterprises (developed 1950s)', '[{"year": 1950, "event": "Soviet-era development of Lviv-Volyn basin commenced"}, {"year": 1991, "event": "Transferred to Ukrainian state on independence as Lvivvuhillia and Volynvuhillia"}, {"year": 2015, "event": "State support to coal mining companies withdrawn — severe financial crisis"}, {"year": 2015, "event": "Cabinet approved liquidation of Zarichna mine (Lvivvuhillia) and Mine No.9 Novovolynska (Volynvuhillia)"}, {"year": 2025, "event": "Operations severely disrupted by war; several mines in care-and-maintenance or closed"}]'::jsonb, '[{"year": 1950, "event": "Basin developed under Soviet 5-year plans — 18 mines at peak"}, {"year": 2006, "event": "18 mines active producing approximately 6 million tonnes/year"}, {"year": 2015, "event": "Multiple mines liquidated; arrears of 3 months'' wages at state-owned mines"}, {"year": 2019, "event": "Production declining sharply — basin extending into Poland (Lublin Basin)"}, {"year": 2025, "event": "War impact — logistics severely disrupted; western Ukraine supply chain stressed"}]'::jsonb, '[{"year": 2015, "event": "Parliament reallocated UAH 900 million for miner wages after protests — still insufficient"}]'::jsonb, NULL, 'Bituminous coal (sub-bituminous to steam coal)', 'Bituminous — medium calorific value; lower than Donbas', 4800.0, 10.0, 24.0, 1.8, NULL, NULL, NULL, 'Underground — longwall; depths 500–1,000m; seams 0.8–1.0m', NULL, 'OPERATIONAL BUT SEVERELY DISRUPTED — domestic supply to DTEK Dobrotvirska (510MW) and Burshtynska (2,181MW) power plants', NULL, NULL, 'Domestic supply only — export restricted wartime', 'Odesa (via long rail haul); Polish border possible', '["Rail (Ukrainian railway — Ukrzaliznytsia)"]'::jsonb, NULL, FALSE, '[]'::jsonb)
