VALUES ('Kellingley Colliery — Yorkshire', 'UK Coal plc — Closed 18 December 2015', NULL, NULL, NULL, 'United Kingdom', 'North Yorkshire, Yorkshire Coalfield', 'Kellingley, near Knottingley, North Yorkshire, England, UK', 53.698, -1.222, 'Goole (15 km east) or Hull (45 km east)', 'Knottingley railway station (East Coast via Ferrybridge junction)', 1960, 55, 'National Coal Board (NCB)', '[{"year": 1960, "event": "Shaft sinking commenced by National Coal Board"}, {"year": 1965, "event": "First coal production"}, {"year": 1994, "event": "Privatized as RJB Mining on NCB privatization"}, {"year": 2001, "event": "Became UK Coal plc"}, {"year": 2015, "event": "Closed December 18 — end of deep coal mining in Britain; 450 miners redundant"}]'::jsonb, '[{"year": 1960, "event": "Shaft sinking started — innovative freeze-boring through waterlogged geology to 640ft"}, {"year": 1965, "event": "First production — twin shafts each 800m deep"}, {"year": 1984, "event": "Miners'' strike — higher-than-average opposition to strike at Kellingley; Joe Green killed on picket line"}, {"year": 1986, "event": "Record 404,000 tonnes in single shift"}, {"year": 2015, "event": "December 18 — last shift worked; Britain''s deep coal mining ended"}, {"year": 2016, "event": "BBC documentary ''The Last Miners'' broadcast about final weeks"}]'::jsonb, '[{"year": 1984, "event": "Joe Green killed by lorry on picket line during miners'' strike"}, {"year": 2008, "event": "Miner Don Cook died in rock fall"}, {"year": 2009, "event": "Ian Cameron died after equipment fell on him"}]'::jsonb, 0, 'Bituminous coal', 'Bituminous — medium to high grade; Barnsley Bed seam coal', 6200.0, 6.5, 12.0, 1.4, NULL, 0.0, 0.0, 'Underground — longwall (800m deep; twin shafts)', NULL, 'CLOSED December 18, 2015 — Britain''s last deep pit; site earmarked for commercial redevelopment', NULL, NULL, 'CLOSED', 'Goole or Hull (historically)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
