VALUES ('Hatfield Main Colliery — South Yorkshire', 'Hatfield Colliery Partnership Ltd (HCPL) — Closed June 2015', NULL, NULL, NULL, 'United Kingdom', 'South Yorkshire Coalfield, Doncaster District', 'Stainforth, Doncaster, South Yorkshire, England, UK', 53.5795, -1.0285, 'Goole (22 km east)', 'Hatfield and Stainforth railway station', 1911, 104, 'Hatfield Main Colliery Company', '[{"year": 1911, "event": "First shaft sunk using Francois Cementation Process"}, {"year": 1921, "event": "Second shaft sunk"}, {"year": 1927, "event": "Acquired by Carlton Main Colliery Company"}, {"year": 1947, "event": "Nationalized into National Coal Board"}, {"year": 1993, "event": "Closed by British Coal; reopened 1994 by management buyout as Hatfield Coal Company Ltd"}, {"year": 2001, "event": "Closed August 9 — mothballed with DTI funding"}, {"year": 2001, "event": "Coalpower Ltd (Richard Budge) took control"}, {"year": 2013, "event": "Employee buyout — Hatfield Colliery Partnership Ltd (HCPL) purchased from ING Bank"}, {"year": 2015, "event": "Closed June 2015 — 430 jobs lost; ''can''t find a market for the coal''"}]'::jsonb, '[{"year": 1911, "event": "First shaft sunk — High Hazel seam target"}, {"year": 1939, "event": "Worst accident — cage overshot in upcast shaft; 1 killed, 50 injured"}, {"year": 1984, "event": "Miners'' strike participation"}, {"year": 1994, "event": "Reopened after buyout — made £2.4M profit in first year"}, {"year": 2013, "event": "Became worker-owned — unique employee buyout from ING Bank"}, {"year": 2014, "event": "NUM provided £4 million bridging finance for new coal face"}, {"year": 2015, "event": "Final closure June 2015 — last coal given to Mayor of Doncaster"}]'::jsonb, '[{"year": 1939, "event": "Cage accident in upcast shaft — 1 killed, 50 injured"}, {"year": 2013, "event": "Major spoil heap slip due to rainfall"}]'::jsonb, 0, 'Bituminous coal (High Hazel seam)', 'Bituminous — medium grade coking/steam coal', 6100.0, 7.0, 13.0, 1.5, NULL, 0.0, 0.0, 'Underground — longwall', NULL, 'CLOSED June 2015 — final coal to Mayor of Doncaster', NULL, NULL, 'CLOSED', 'Goole (historically)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
