VALUES ('Tower Colliery — South Wales Coalfield', 'Tower Colliery Ltd (employee buyout) — Closed January 2008', NULL, NULL, NULL, 'United Kingdom', 'South Wales Coalfield, Rhondda Cynon Taf', 'Hirwaun, Rhondda Cynon Taf, Wales, UK', 51.7077, -3.5127, 'Cardiff (40 km south) or Port Talbot (35 km southwest)', 'Aberdare line (Hirwaun area)', 1864, 144, 'Various private companies (Victorian era)', '[{"year": 1864, "event": "Sinking commenced — Hirwaun area South Wales anthracite/steam coal"}, {"year": 1947, "event": "Nationalised into NCB"}, {"year": 1994, "event": "British Coal closure order — 239 miners each invested £8,000 life savings in employee buyout"}, {"year": 1995, "event": "Reopened as Tower Colliery Ltd — historic employee buyout model"}, {"year": 2008, "event": "Closed January 25 — coal reserves exhausted after 144 years of mining"}]'::jsonb, '[{"year": 1994, "event": "Employee buyout — miners mortgaged homes, invested life savings to save colliery"}, {"year": 1995, "event": "Reopened — became symbol of labour movement and workers'' self-management"}, {"year": 2008, "event": "January 25 — final coal — reserves exhausted; employee-owners received payouts from profitable operations"}]'::jsonb, '[{"year": 1994, "event": "Closure threat — mass community campaign; 239 miners risked personal savings"}]'::jsonb, 0, 'Steam coal / anthracite (South Wales seams)', 'High-quality steam coal / anthracite', 6800.0, 4.5, 8.0, 0.8, NULL, 0.0, 0.0, 'Underground — longwall', NULL, 'CLOSED January 2008 — reserves exhausted; famous for 1994 employee buyout', NULL, NULL, 'CLOSED', 'Port Talbot or Cardiff (historically)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
