INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Ffos-y-fran Opencast Mine — South Wales', 'Merthyr (South Wales) Ltd (Gwent Investments Ltd) — Closed November 2023', NULL, NULL, NULL, 'United Kingdom', 'South Wales Coalfield, Merthyr Tydfil', 'East Merthyr, Merthyr Tydfil, Wales, UK', 51.7536, -3.3442, 'Cardiff (35 km south) or Port Talbot (30 km southwest)', 'Cwmbargoed washery rail siding → Rhymney Line → Cardiff → Vale of Glamorgan Line → Port Talbot', 2008, 15, 'Miller Argent (South Wales) Ltd (Miller Group + Argent Group + Bernard Llewellyn)', '[{"year": 2008, "event": "Opened under Miller Argent — East Merthyr Reclamation Scheme Phase III"}, {"year": 2015, "event": "David Stanley Lewis / Merthyr (South Wales) Ltd took over operations"}, {"year": 2022, "event": "Planning permission expired September 2022 — mining continued illegally"}, {"year": 2023, "event": "Closed November 2023 — last major opencast in UK; 100+ jobs lost; restoration disputed"}]'::jsonb, '[{"year": 2007, "event": "Welsh Assembly approved scheme (second attempt after High Court quash)"}, {"year": 2008, "event": "Operations commenced — 367 hectares; planned 10 Mt over 15 years"}, {"year": 2017, "event": "Last rail delivery to Aberthaw Power Station; subsequent sales to Tata Steel Port Talbot"}, {"year": 2022, "event": "Planning permission expired September 6 — illegal mining continued ~15 months"}, {"year": 2023, "event": "November — mining ceased; 11.25 Mt total extracted; UK''s last opencast coal mine closed"}, {"year": 2024, "event": "Restoration controversy — pumps removed; void filling with water; £37M overburden problem"}, {"year": 2025, "event": "Senedd inquiry found restoration ''woefully short of promises''; Merthyr (South Wales) Ltd refusing full restoration funding"}]'::jsonb, '[{"year": 2008, "event": "Extinction Rebellion / environmental protest — site occupied on ''Fossil Fools Day''"}, {"year": 2022, "event": "15 months of illegal mining after planning permission expired — company made record profits during Russia sanctions-driven price surge"}, {"year": 2024, "event": "Pumps removed from void — 37M cubic metres of overburden; void filling with water; safety concerns for 58,000 Merthyr residents"}]'::jsonb, 0, 'Bituminous coal (South Wales high-quality steam and coking coal)', 'High-quality bituminous — low ash, low sulfur; suitable for Tata Steel coking', 6800.0, 5.5, 8.5, 0.75, NULL, 0.0, 0.0, 'Open-pit / opencast — 1,000 acres, 180m depth; conveyor to on-site washery', NULL, 'CLOSED November 2023 — produced 11.25 Mt total; responsible for 86% of UK''s coal output in final years', NULL, NULL, 'CLOSED', 'Port Talbot (via Vale of Glamorgan Line rail)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
