INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Longannet Opencast Complex — Scottish Coalfields', 'Scottish Coal (Scottish Resources Group) — Scottish Coal bust April 2013', NULL, NULL, NULL, 'United Kingdom', 'Scottish Central Belt Coalfields (Fife, Ayrshire, Lanarkshire)', 'Kincardine / Clackmannanshire area, Fife / Stirling, Scotland, UK', 56.042, -3.716, 'Grangemouth (20 km east) or Leith (30 km east)', 'Stirling–Dunfermline line (Longannet colliery siding)', 1960, 53, 'National Coal Board; Scottish Coal (Scottish Resources Group) post-privatization', '[{"year": 1960, "event": "Longannet opencast scheme commenced for Longannet power station (2,400 MW)"}, {"year": 1994, "event": "Privatized under Scottish Coal / Scottish Resources Group"}, {"year": 2013, "event": "Scottish Coal (SRG) went bust April 2013 — largest coal mining company collapse in UK post-privatization"}, {"year": 2013, "event": "Mines in Ayrshire, Lanarkshire, Fife abandoned — rising water, contaminated lagoons, erosion"}, {"year": 2016, "event": "Hargreaves plc closed St. Ninians and Muir Dean (Fife) — last Scottish open pit operations"}]'::jsonb, '[{"year": 1960, "event": "Scottish Central Belt opencast coal development for Longannet 2,400 MW power station"}, {"year": 2010, "event": "Over 13 million tonnes Scottish opencast production"}, {"year": 2013, "event": "Scottish Coal bankruptcy — largest British mining company failure post-privatization"}, {"year": 2013, "event": "Sunday Herald July 2013: mines in 3 Scottish regions threatened by rising water and environmental damage"}, {"year": 2015, "event": "Longannet power station closed March 24 — Scotland''s last coal power plant"}, {"year": 2016, "event": "Final Scottish opencast closures by Hargreaves"}, {"year": 2022, "event": "Scottish Government announced de-facto ban on coal mining"}]'::jsonb, '[{"year": 2013, "event": "Scottish Coal bankruptcy — abandoned mines with rising water, contaminated lagoons and erosion threatening environment"}, {"year": 2015, "event": "Longannet power station closed — end of Scottish coal power generation"}]'::jsonb, 0, 'Bituminous coal (Scottish Central Belt — mixed steam and coking quality)', 'Bituminous — medium grade', 6000.0, 8.0, 14.0, 1.3, NULL, 0.0, 0.0, 'Open-pit / opencast (closed) — shallow seams in Central Belt', NULL, 'CLOSED — Scottish Coal went bust 2013; last operations closed 2016; Scotland de-facto mining ban 2022', NULL, NULL, 'CLOSED', 'Grangemouth (historically)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
