VALUES ('Betteshanger Colliery — Kent Coalfield', 'British Coal (NCB) — Closed August 1989', NULL, NULL, NULL, 'United Kingdom', 'Kent Coalfield, Deal area, Kent', 'Betteshanger, near Deal, Kent, England, UK', 51.23, 1.33, 'Dover (15 km south) or Sandwich Haven', 'Deal railway station (2 km); Sandwich station; SE mainline', 1924, 65, 'Pearson and Dorman Long Ltd', '[{"year": 1924, "event": "Sinking commenced by Pearson and Dorman Long Ltd"}, {"year": 1927, "event": "First coal production"}, {"year": 1947, "event": "Nationalised into NCB"}, {"year": 1989, "event": "Closed August 1989 — last Kent coalfield mine; end of Kent coal industry"}]'::jsonb, '[{"year": 1924, "event": "Sinking commenced in concealed Kent coalfield (discovered 1890)"}, {"year": 1984, "event": "Betteshanger miners refused to return during miners'' strike — one of most militant pits in UK"}, {"year": 1987, "event": "Snowdown Colliery (Kent) closed — penultimate Kent mine"}, {"year": 1989, "event": "August — closed; coal mining in Kent ended after 65 years; site now Fowlmead Country Park"}]'::jsonb, '[{"year": 1932, "event": "Betteshanger strike — major labour dispute; historical significance"}, {"year": 1984, "event": "Miners'' strike — Betteshanger among most militant; refused to return"}]'::jsonb, 0, 'Bituminous coal (Kent concealed coalfield)', 'Bituminous — Carboniferous Westphalian measures', 6400.0, 6.0, 11.0, 1.8, NULL, 0.0, 0.0, 'Underground — longwall (closed August 1989)', NULL, 'CLOSED August 1989 — site now Fowlmead Country Park heritage site', NULL, NULL, 'CLOSED', 'Dover (historically — unique proximity to continent)', '[]'::jsonb, NULL, FALSE, '[]'::jsonb)
